import{_ as t,o as r,c as n,ah as o}from"./chunks/framework.C-FRNfAJ.js";const u=JSON.parse('{"title":"Results and certification","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/coordinateur/resultats.md","filePath":"src/en/guide/coordinateur/resultats.md"}'),a={name:"en/guide/coordinateur/resultats.md"};function s(i,e,d,h,c,l){return r(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="results-and-certification" tabindex="-1">Results and certification <a class="header-anchor" href="#results-and-certification" aria-label="Permalink to &quot;Results and certification&quot;">​</a></h1><p>From a cohort page, <strong>Attendance</strong> and <strong>Results</strong> give the tracking of learners. There you enter the jury&#39;s decisions, produce the report and issue certificates.</p><h2 id="following-attendance-and-grades" tabindex="-1">Following attendance and grades <a class="header-anchor" href="#following-attendance-and-grades" aria-label="Permalink to &quot;Following attendance and grades&quot;">​</a></h2><p>The pages are the same as the Lead Trainer&#39;s: see <a href="./../equipe/formateur.html#attendance">Lead Trainer</a>. In addition, you can <strong>enter and correct in-person attendance</strong> in the trainer&#39;s place, and <strong>open retakes</strong>.</p><p>Reminder: as long as the <strong>Sève course id</strong> is not entered on the cohort, neither virtual classes nor grades flow back. The page tells you so.</p><h2 id="the-jury-s-decisions" tabindex="-1">The jury&#39;s decisions <a class="header-anchor" href="#the-jury-s-decisions" aria-label="Permalink to &quot;The jury&#39;s decisions&quot;">​</a></h2><p>Only you (and the Administrator) enter the jury, <strong>from the cohort&#39;s start</strong>. On the <strong>Results</strong> page, click the learner then <strong>Enter decisions</strong>. Each decision stays <strong>pending</strong> until the jury has taken it; grades are optional and <strong>do not count in the average</strong>.</p><table tabindex="0"><thead><tr><th>Decision</th><th>What you enter</th></tr></thead><tbody><tr><td><strong>Tutored project</strong></td><td>Subject, validated or not, grade out of 20</td></tr><tr><td><strong>Defence</strong></td><td>Date, validated or not, grade out of 20</td></tr><tr><td><strong>Internship</strong></td><td>Host company (reused from the internship agreement if any), validated or not</td></tr></tbody></table><p>A validated <strong>defence</strong> is one of the certificate&#39;s conditions. The <strong>internship</strong> never blocks the certificate.</p><h3 id="the-jury-president" tabindex="-1">The jury president <a class="header-anchor" href="#the-jury-president" aria-label="Permalink to &quot;The jury president&quot;">​</a></h3><p>Enter the <strong>jury president</strong> with the decisions: they sign the certificate, and their name is printed on it. <strong>Without a president, the certificate cannot be issued.</strong></p><h3 id="the-jury-members" tabindex="-1">The jury members <a class="header-anchor" href="#the-jury-members" aria-label="Permalink to &quot;The jury members&quot;">​</a></h3><p>Under <strong>Jury members</strong>, add for each <strong>defence date</strong> the members present: name and e-mail address, with no Kura account. Each receives a <strong>token</strong>, due once the defences are held. See <a href="./remunerations.html">Remunerations and commissions</a>.</p><h2 id="the-defence-report" tabindex="-1">The defence report <a class="header-anchor" href="#the-defence-report" aria-label="Permalink to &quot;The defence report&quot;">​</a></h2><p>When the jury has <strong>decided on the defence of every confirmed learner</strong> of the cohort, the page&#39;s <strong>Documents</strong> panel offers <strong>Generate the report</strong>. The report is <strong>numbered</strong> (<code>PVS-NB-YYYY-XXX</code>), <strong>sealed</strong> and kept.</p><p>It is <strong>never regenerated on viewing</strong>. If the jury&#39;s decisions are corrected afterwards, the page offers to generate a new one: it <strong>replaces</strong> the old one, which stays downloadable, marked &quot;replaced&quot;. As long as a defence has no decision, no report is produced.</p><h2 id="issuing-the-certificate" tabindex="-1">Issuing the certificate <a class="header-anchor" href="#issuing-the-certificate" aria-label="Permalink to &quot;Issuing the certificate&quot;">​</a></h2><p>On the results page, the <strong>Certification</strong> block shows each learner&#39;s four conditions, met or not:</p><ol><li>every block graded, <strong>average ≥ 10/20</strong>;</li><li><strong>no block under 8/20</strong>;</li><li><strong>defence validated</strong> by the jury;</li><li><strong>training fees paid in full</strong>.</li></ol><p>No condition compensates for another. When all four are met and the jury president is entered, <strong>Deliver the certificate</strong> is available, <strong>once only</strong> per learner.</p><p>Issuance:</p><ul><li>freezes a <strong>sealed PDF</strong> (<code>CERT-NB-YYYY-XXX</code>) with the <strong>mention</strong> (Passable from 10/20; Assez bien, Bien and Très bien at the thresholds the Administrator sets, 12, 14 and 16 by default), and the <strong>transcript of competencies</strong> (<code>REL-NB-YYYY-XXX</code>), sent to the learner by e-mail;</li><li><strong>ends the enrolment</strong>;</li><li>removes the learner from their cohort&#39;s course in Sève;</li><li>moves their account to the <strong>Canopé</strong> state and enrols them in the <strong>Canopé Journey</strong>.</li></ul><p>If the Canopé Journey&#39;s Sève course is not yet entered, the Canopé enrolment <strong>waits</strong> until it is.</p><h2 id="the-partial-attestation" tabindex="-1">The partial attestation <a class="header-anchor" href="#the-partial-attestation" aria-label="Permalink to &quot;The partial attestation&quot;">​</a></h2><p>For a <strong>dropped</strong> enrolment (voluntary or for non-payment) with <strong>at least one validated block</strong>, <strong>Deliver the partial attestation</strong> produces an attestation that lists the validated blocks, those not validated or not followed, and the reason for the interruption, with the transcript of competencies. There is <strong>never a partial certificate</strong>. If no block is validated, there is nothing to attest.</p>',25)])])}const p=t(a,[["render",s]]);export{u as __pageData,p as default};
